PROC FORMAT;
    VALUE sev_fmt
        LOW - 1000      = 'ATTRITIONAL'
        1000.01 - 10000 = 'LARGE_LOSS'
        10000.01 - HIGH = 'CATASTROPHIC'
        OTHER           = 'UNKNOWN';
RUN;

DATA work.claims_banded;
    SET raw.claims;
    WHERE loss_date >= '01JAN2025'd AND claim_status NE 'OPEN';
    severity_band = PUT(reserve_amount, sev_fmt.);
    loss_year = YEAR(loss_date);
RUN;

PROC MEANS DATA=work.claims_banded NOPRINT NWAY;
    CLASS loss_year cause_code severity_band;
    VAR reserve_amount;
    OUTPUT OUT=out.severity_summary (DROP=_TYPE_ _FREQ_)
        N=claim_volume
        SUM=total_reserves
        MEAN=avg_reserve;
RUN;

PROC SORT DATA=raw.payments OUT=work.sorted_payments;
    BY claim_id payment_date payment_id;
RUN;

DATA out.claim_payment_rollup;
    SET work.sorted_payments;
    BY claim_id;
    RETAIN cumulative_paid indemnity_count first_pay_date;
    IF FIRST.claim_id THEN DO;
        cumulative_paid = 0;
        indemnity_count = 0;
        first_pay_date = payment_date;
    END;
    IF payment_type = 'INDEMNITY' THEN DO;
        indemnity_count + 1;
        cumulative_paid + COALESCE(paid_amount, 0);
    END;
    ELSE IF payment_type = 'SALVAGE' THEN DO;
        cumulative_paid + COALESCE(paid_amount, 0);
    END;
    days_since_first_pay = payment_date - first_pay_date;
    IF LAST.claim_id THEN OUTPUT;
    KEEP claim_id cumulative_paid indemnity_count first_pay_date payment_date days_since_first_pay;
RUN;

%LET regions = DUBLIN LEINSTER MUNSTER CONNACHT;
%LET leakage_threshold = 1.25;

%MACRO run_leakage_audit;
    %LOCAL i curr_region;
    %LET i = 1;
    %LET curr_region = %SCAN(&regions, &i);
    %DO %WHILE(&curr_region NE );
        PROC SQL;
            CREATE TABLE work.audit_&curr_region AS
            SELECT 
                "&curr_region" AS audit_region LENGTH=15,
                c.claim_id,
                p.policy_id,
                c.reserve_amount,
                SUM(COALESCE(pay.paid_amount, 0)) AS actual_paid,
                CALCULATED actual_paid / NULLIF(c.reserve_amount, 0) AS paid_to_reserve_ratio
            FROM raw.policies p
            INNER JOIN raw.claims c ON p.policy_id = c.policy_id
            LEFT JOIN raw.payments pay ON c.claim_id = pay.claim_id
            WHERE p.region = "&curr_region"
              AND c.claim_status = 'CLOSED'
            GROUP BY c.claim_id, p.policy_id, c.reserve_amount
            HAVING CALCULATED paid_to_reserve_ratio > &leakage_threshold;
        QUIT;
        %LET i = %EVAL(&i + 1);
        %LET curr_region = %SCAN(&regions, &i);
    %END;
    DATA out.consolidated_leakage_flags;
        SET work.audit_DUBLIN work.audit_LEINSTER work.audit_MUNSTER work.audit_CONNACHT;
    RUN;
%MEND run_leakage_audit;
%run_leakage_audit;

/* SAS Program: RETENTION_SUMMARY_STATS */
DATA WORK.POLICY_CLASSIFIED;
    SET INLIB.POLICY_BASE;
    IF TenureMonths < 12 THEN TenureBand = 'NEW';
    ELSE IF TenureMonths <= 36 THEN TenureBand = 'MID';
    ELSE TenureBand = 'LOYAL';
    IF RenewedFlag = 1 THEN RenewCount = 1;
    ELSE RenewCount = 0;
RUN;

PROC SORT DATA=WORK.POLICY_CLASSIFIED;
    BY Region TenureBand;
RUN;

PROC MEANS DATA=WORK.POLICY_CLASSIFIED N MEAN SUM NOPRINT;
    BY Region TenureBand;
    VAR RenewCount Premium;
    OUTPUT OUT=WORK.RETENTION_METRICS 
        N=TotalPolicies 
        SUM(RenewCount)=RenewedPolicies
        MEAN(Premium)=AvgPremium;
RUN;

/* SAS Program: ACTUARIAL_DEVELOPMENT_TRIANGLE */
PROC SORT DATA=INLIB.INCREMENTAL_LOSSES OUT=WORK.SORTED_LOSSES;
    BY AccidentYear DevelopmentYear;
RUN;

DATA WORK.CUMULATIVE_TRIANGLES;
    SET WORK.SORTED_LOSSES;
    BY AccidentYear DevelopmentYear;

    RETAIN CumPaidLoss 0;

    IF FIRST.AccidentYear THEN CumPaidLoss = 0;
    CumPaidLoss + IncrementalPaid;

    UltimateEstimate = CumPaidLoss * DevelopmentFactor;
    OUTPUT;
RUN;

/* SAS Program: MORTALITY_EXPERIENCE_STUDY */
DATA WORK.MORTALITY_SCORED;
    SET INLIB.LIFE_POLICY_EXPOSURE;
    IF AttainedAge < 40 THEN AgeGroup = 'UNDER_40';
    ELSE IF AttainedAge <= 65 THEN AgeGroup = '40_TO_65';
    ELSE AgeGroup = 'OVER_65';
    ExpectedClaims = ExposureUnits * BaseMortalityRate;
RUN;

PROC SUMMARY DATA=WORK.MORTALITY_SCORED NWAY;
    CLASS AgeGroup Gender;
    VAR ExposureUnits ActualDeaths ExpectedClaims;
    OUTPUT OUT=WORK.MORTALITY_EXPERIENCE (DROP=_TYPE_ _FREQ_)
        SUM(ExposureUnits)=TotalExposure
        SUM(ActualDeaths)=TotalActualDeaths
        SUM(ExpectedClaims)=TotalExpectedClaims;
RUN;
